use vstd::prelude::*;

verus! {
    // Given a vector of non‐empty character vectors `l`,
    // return a vector `res` whose length equals `l.len()`
    // and whose i-th element is the last character of `l[i]`.
    fn extract_rear_chars(l: &Vec<Vec<char>>) -> (res: Vec<char>)
        requires
            // every inner vector is non‐empty
            forall|i: usize| i < l.len() ==> l.index(i).len() > 0,
        ensures
            // output length equals number of inner vectors
            res.len() == l.len(),
            // each output character is the last character of the corresponding inner vector
            forall|i: usize| i < l.len() ==>
                res.index(i) == l.index(i).index(l.index(i).len() - 1),
    {
        let mut res: Vec<char> = Vec::new();
        let mut i: usize = 0;
        // iterate over all inner vectors
        while i < l.len()
            invariant
                // loop variable stays in range
                i <= l.len(),
                // we've pushed exactly `i` characters so far
                res.len() == i,
                // for each j < i, res[j] is the last char of l[j]
                forall|j: usize| j < i ==>
                    res.index(j) == l.index(j).index(l.index(j).len() - 1),
            decreases l.len() - i
        {
            let inner = &l[i];
            let last_idx = inner.len() - 1;
            let c = inner[last_idx];
            res.push(c);
            i += 1;
        }
        res
    }
}

fn main() {
    // example usage:
    let a: Vec<Vec<char>> = vec![vec!['h','i'], vec!['b','y','e'], vec!['!']];
    let out = extract_rear_chars(&a);
    // out == vec!['i', 'e', '!']
}